        phone.setValueChangeMode(ValueChangeMode.EAGER);
        message.setValueChangeMode(ValueChangeMode.EAGER);

        // Only the rules in validate() decide what is invalid, not the browser's own e-mail check.
        email.setManualValidation(true);

        // Any edit re-enables Send after a successful send.
        name.addValueChangeListener(e -> send.setEnabled(true));
        email.addValueChangeListener(e -> send.setEnabled(true));
        phone.addValueChangeListener(e -> send.setEnabled(true));
