+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(EmailValidator.PATTERN);
+
+    private final ContactMessageService messages;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingLeave;
+
+    public ContactView(ContactMessageService messages) {
+        this.messages = messages;
+
+        // Eager syncing makes every keystroke an edit, for the Send button and for the leave check.
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+
+        // Only the rules in validate() decide what is invalid, not the browser's own e-mail check.
+        email.setManualValidation(true);
+
+        // Any edit re-enables Send after a successful send.
+        name.addValueChangeListener(e -> send.setEnabled(true));
+        email.addValueChangeListener(e -> send.setEnabled(true));
+        phone.addValueChangeListener(e -> send.setEnabled(true));
+        message.addValueChangeListener(e -> send.setEnabled(true));
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(e -> submit());
+
+        // Enter sends from anywhere in the view. The default blocks the browser's own Enter action, so Shift+Enter
+        // is the only way to start a new line in the message.
+        Shortcuts.addShortcutListener(this, this::submitIfEnabled, Key.ENTER);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+
+        // The header becomes the dialog's accessible name, so it must not contain a field label such as "Message".
+        leaveDialog.setHeaderTitle("Leave this page?");
+        leaveDialog.add(new Paragraph("Leaving this page throws away what you have typed."));
+        leaveDialog.getFooter().add(
+                new Button("Keep editing", e -> leaveDialog.close()),
+                new Button("Discard", e -> discardAndLeave()));
+        // Closing the dialog any way other than Discard (Keep editing, Esc, click outside) keeps the user here.
+        leaveDialog.addOpenedChangeListener(e -> {
+            if (!e.isOpened()) {
+                cancelPendingLeave();
+            }
+        });
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class),
+                new FormLayout(name, email, phone, message), send, grid, leaveDialog);
+        refreshGrid();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsentInput()) {
+            cancelPendingLeave();
+            pendingLeave = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private boolean hasUnsentInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty() || !phone.getValue().isEmpty()
+                || !message.getValue().isEmpty();
+    }
+
+    private void discardAndLeave() {
+        ContinueNavigationAction leave = pendingLeave;
+        pendingLeave = null;
+        leaveDialog.close();
+        leave.proceed();
+    }
+
+    // The browser waits for the server to settle a postponed navigation. cancel() settles it, so the next
+    // click on the same link is seen again instead of being dropped.
+    private void cancelPendingLeave() {
+        if (pendingLeave != null) {
+            ContinueNavigationAction leave = pendingLeave;
+            pendingLeave = null;
+            leave.cancel();
+        }
+    }
+
+    private void submitIfEnabled() {
+        if (send.isEnabled()) {
+            submit();
+        }
+    }
+
+    private void submit() {
+        if (!validate()) {
+            return;
+        }
+        messages.add(new ContactMessage(name.getValue().trim(), email.getValue().trim(), phone.getValue().trim(),
+                message.getValue()));
+        Notification.show("Message sent");
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        // Clearing the fields counts as edits and re-enabled Send, so disable it last.
+        send.setEnabled(false);
+        refreshGrid();
+    }
+
+    private boolean validate() {
+        String nameError = name.getValue().isBlank() ? "Name is required" : null;
+        String emailError = emailError();
+        String messageError = messageError();
+
+        showError(name, nameError);
+        showError(email, emailError);
+        showError(message, messageError);
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private String emailError() {
+        String address = email.getValue().trim();
+        if (!address.isEmpty()) {
+            return EMAIL_PATTERN.matcher(address).matches() ? null : "Enter a valid e-mail address";
+        }
+        return phone.getValue().isBlank() ? "Give an e-mail address or a phone number" : null;
+    }
+
+    private String messageError() {
+        String text = message.getValue();
+        if (text.isBlank()) {
+            return "Message is required";
+        }
+        // Count code points, so one emoji counts as one character.
+        if (text.codePointCount(0, text.length()) > MAX_MESSAGE_LENGTH) {
+            return "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+        return null;
+    }
+
+    private static void showError(HasValidation field, String error) {
+        field.setInvalid(error != null);
+        field.setErrorMessage(error);
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messages.findAllNewestFirst());
+    }
+}
