+        page.keyboard().type("second line");
+
+        assertThat(page.getByLabel("Message")).hasValue("first line\nsecond line");
+        assertThat(page.getByText("Message sent")).isHidden();
+        assertThat(page.getByLabel("Name")).hasValue("Browser Cy");
+    }
+
+    @Test
+    void plainEnterOnAnInvalidFormShowsErrorsAndAddsNoLine() {
+        page.navigate(getUrl());
+        page.getByLabel("Message").fill("no new line");
+
+        page.getByLabel("Message").press("Enter");
+
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByLabel("Message")).hasValue("no new line");
+    }
+
+    @Test
+    void sendingAnEmptyFormShowsTheErrors() {
+        page.navigate(getUrl());
+
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Send")).click();
+
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Give an e-mail address or a phone number")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+        assertThat(page.getByText("Message sent")).isHidden();
+    }
+
+    @Test
+    void leavingWithTypedTextAsksAndDiscardGoesToAbout() {
+        page.navigate(getUrl());
+        page.getByLabel("Name").fill("Browser Ben");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        // The dialog host element has no size of its own, so check for the dialog through its buttons.
+        assertThat(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing"))).isVisible();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+        assertThat(page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing"))).isHidden();
+        assertThat(page.getByLabel("Name")).hasValue("Browser Ben");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+
+        assertThat(page).hasURL(Pattern.compile(".*/about$"));
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+    }
+}
