+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertSame;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.test.annotation.DirtiesContext;
+
+// The message list is shared by the whole application context, so these tests compare counts and
+// their own unique names rather than assuming an empty list. The context is discarded afterwards
+// so no other test class sees the messages sent here.
+@SpringBootTest
+@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_CLASS)
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void showsHeadingAboutLinkAndEmptyFormWithSendEnabled() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("About", $(RouterLink.class).single().getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void aboutViewShowsItsHeading() {
+        navigate(AboutView.class);
+
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyFormShowsEveryRequiredErrorAndSendsNothing() {
+        navigate(ContactView.class);
+        int before = gridItems().size();
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse($(Notification.class).exists());
+        assertEquals(before, gridItems().size());
+    }
+
+    @Test
+    void blankNameAndBlankMessageAreRejectedEvenWhenContactIsGiven() {
+        navigate(ContactView.class);
+        test(email()).setValue("someone@example.com");
+        test(name()).setValue("   ");
+        test(message()).setValue("  ");
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertFalse(email().isInvalid());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void malformedEmailIsRejectedAndPhoneAloneIsEnough() {
+        navigate(ContactView.class);
+        test(name()).setValue("Mallory");
+        test(message()).setValue("Hello");
+        test(email()).setValue("not-an-address");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse($(Notification.class).exists());
+
+        test(email()).clear();
+        test(phone()).setValue("+358 40 123 4567");
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertFalse(phone().isInvalid());
+        assertTrue($(Notification.class).exists());
+    }
+
+    @Test
+    void messageLongerThan500CharactersIsRejected() {
+        navigate(ContactView.class);
+        test(name()).setValue("Long Winded");
+        test(email()).setValue("long@example.com");
+
+        test(message()).setValue("x".repeat(501));
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertFalse($(Notification.class).exists());
+
+        test(message()).setValue("x".repeat(500));
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertTrue($(Notification.class).exists());
+    }
+
+    @Test
+    void validMessageIsSentAndTheFormIsClearedUntilTheNextEdit() {
+        navigate(ContactView.class);
+        int before = gridItems().size();
+        test(name()).setValue("Alice Sent");
+        test(email()).setValue("alice@example.com");
+        test(phone()).setValue("0401234567");
+        test(message()).setValue("Hello there");
+
+        test(send()).click();
+
+        assertEquals("Message sent", test($(Notification.class).single()).getText().strip());
+        assertEquals(before + 1, gridItems().size());
+        ContactMessage row = gridItems().get(0);
+        assertEquals("Alice Sent", row.name());
+        assertEquals("alice@example.com", row.email());
+        assertEquals("0401234567", row.phone());
+        assertEquals("Hello there", row.message());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+
+        test(phone()).setValue("0501234567");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterSendsAValidMessageAndDoesNothingOnceSendIsDisabled() {
+        navigate(ContactView.class);
+        int before = gridItems().size();
+        test(name()).setValue("Enter Key");
+        test(email()).setValue("enter@example.com");
+        test(message()).setValue("Sent with Enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(before + 1, gridItems().size());
+        assertEquals("Enter Key", gridItems().get(0).name());
+        assertFalse(send().isEnabled());
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(before + 1, gridItems().size());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+    }
+
+    @Test
+    void enterSendsOnlyOnceAfterComingBackToTheView() {
+        navigate(ContactView.class);
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+        int before = gridItems().size();
+        test(name()).setValue("Returned Once");
+        test(email()).setValue("once@example.com");
+        test(message()).setValue("one copy");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(before + 1, gridItems().size());
+    }
+
+    @Test
+    void enterOnAnInvalidFormShowsTheSameErrorsAsSend() {
+        navigate(ContactView.class);
+        int before = gridItems().size();
+
+        fireShortcut(Key.ENTER);
+
+        assertTrue(name().isInvalid());
+        assertTrue(message().isInvalid());
+        assertEquals(before, gridItems().size());
+    }
+
+    @Test
+    void sentMessagesAreNewestFirstAndSurviveLeavingTheView() {
+        navigate(ContactView.class);
+        sendMessage("First Sender", "first@example.com", "first message");
+        sendMessage("Second Sender", "second@example.com", "second message");
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        List<ContactMessage> items = gridItems();
+        assertEquals("Second Sender", items.get(0).name());
+        assertEquals("First Sender", items.get(1).name());
+        assertEquals("second message", items.get(0).message());
+    }
+
+    @Test
+    void leavingWithUnsentInputAsksFirstAndKeepEditingStaysOnTheView() {
+        ContactView view = navigate(ContactView.class);
+        test(name()).setValue("Keep Me");
+
+        test($(RouterLink.class).single()).click();
+
+        assertTrue(test($(Dialog.class).single()).isOpen());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertFalse($(Dialog.class).exists());
+        assertSame(view, getCurrentView());
+        assertEquals("Keep Me", name().getValue());
+
+        test($(RouterLink.class).single()).click();
+
+        assertTrue(test($(Dialog.class).single()).isOpen());
+        assertInstanceOf(ContactView.class, getCurrentView());
+    }
+
+    @Test
+    void discardLeavesForTheAboutView() {
+        navigate(ContactView.class);
+        test(message()).setValue("Going to discard this");
+
+        test($(RouterLink.class).single()).click();
+        assertTrue(test($(Dialog.class).single()).isOpen());
+
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void closingTheDialogWithEscapeKeepsTheUserAndAllowsAskingAgain() {
+        navigate(ContactView.class);
+        test(message()).setValue("Still here");
+        test($(RouterLink.class).single()).click();
+
+        test($(Dialog.class).single()).pressEscape();
+
+        assertFalse($(Dialog.class).exists());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(RouterLink.class).single()).click();
+
+        assertTrue(test($(Dialog.class).single()).isOpen());
+        assertInstanceOf(ContactView.class, getCurrentView());
+    }
+
+    @Test
+    void leavingWithAnEmptyFormIsNotInterrupted() {
+        navigate(ContactView.class);
+
+        test($(RouterLink.class).single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse($(Dialog.class).exists());
+    }
+
+    @Test
+    void leavingAfterASuccessfulSendIsNotInterrupted() {
+        navigate(ContactView.class);
+        sendMessage("Leaves Cleanly", "clean@example.com", "all sent");
+
+        test($(RouterLink.class).single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse($(Dialog.class).exists());
+    }
+
+    private void sendMessage(String name, String email, String message) {
+        test(name()).setValue(name);
+        test(email()).setValue(email);
+        test(message()).setValue(message);
+        test(send()).click();
+    }
+
+    private List<ContactMessage> gridItems() {
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        return grid.getListDataView().getItems().toList();
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+}
